24	static inline bool PathIsLegal(const char* cfg)
25	{
26	    mmFileHandle* fd = mmOpenFile(cfg, FILE_READ);
27	    if (fd == NULL) {
28	        return false;
29	    }
30	    (void)mmSeekFile(fd, 0, MM_SEEK_FILE_END);
31	    bool isLegal = mmTellFile(fd) == 0 ? false : true;
32	    mmCloseFile(fd);
33	    return isLegal;
34	}
