36	static void* InitHookFunc(RefObj* obj, const void* userData)
37	{
38	    const rtError_t rtErr = rtInit();
39	    if (rtErr != RT_ERROR_NONE) {
40	        ACL_LOG_INNER_ERROR("rt init fail, ret = %d", rtErr);
41	        return NULL;
42	    }
43	    Status ret = GeInitialize();
44	    if (ret != (Status)SUCCESS) {
45	        ACL_LOG_INNER_ERROR("ge init fail, ret = %d", ret);
46	        (void)rtDeinit();
47	        return NULL;
48	    }
49	    const char* configPath = (const char*)userData;
50	    if (PathIsLegal(configPath)) {
51	        ret = GeDbgInit(configPath);
52	        if (ret != (Status)SUCCESS) {
53	            (void)GeFinalize();
54	            (void)rtDeinit();
55	            return NULL;
56	        }
57	    }
58	    return obj;
59	}
