61	aclError aclInit(const char* configPath)
62	{
63	    if (GetObjRefWithUserData(&gInitRefCount, configPath, InitHookFunc) == NULL) {
64	        ACL_LOG_ERROR("Add refCount err");
65	        return ACL_ERROR_INTERNAL_ERROR;
66	    }
67	    ACL_LOG_INFO("Increased refCount: %lu", (uint64_t)gInitRefCount.refCount);
68	    return ACL_SUCCESS;
69	}
